        +(meta.date   ?'<div class="mc"><div class="ml">Date</div><div class="mv">'+meta.date+'</div></div>':'')
        +(meta.eng    ?'<div class="mc"><div class="ml">Cree par</div><div class="mvo">'+meta.eng+'</div></div>':'')
