      if (!bA || !bB) return;
      var wps = Array.isArray(c.waypoints) ? c.waypoints.filter(function(p){ return p && isFinite(+p.x) && isFinite(+p.y); }).map(function(p){ return { x:+p.x, y:+p.y }; }) : [];
