let TPL_MODE='replace'; // 'replace' | 'append'

function setTplMode(mode){
  TPL_MODE=mode;
  document.getElementById('tpl-mode-replace').classList.toggle('active',mode==='replace');
  document.getElementById('tpl-mode-append').classList.toggle('active',mode==='append');
}

function toggleTplDd(e){
  e.stopPropagation();
  const menu=document.getElementById('tpl-dd-menu');
  const open=menu.classList.toggle('open');
  if(open){renderTplQuickBar();document.addEventListener('click',closeTplDd,{once:true});}
}
function closeTplDd(){document.getElementById('tpl-dd-menu')?.classList.remove('open');}
document.addEventListener('click',e=>{if(!document.getElementById('tpl-dd-wrap')?.contains(e.target))closeTplDd();});

function renderTplQuickBar(){
  const el=document.getElementById('tpl-quick-list');if(!el)return;
  const _et=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const row=(t,mine)=>`
    <div class="tpl-dd-item" role="button" tabindex="0" onclick="applyTemplate('${_jsq(t.id)}');closeTplDd()" onkeydown="if(event.key==='Enter'){applyTemplate('${_jsq(t.id)}');closeTplDd();}">
      <span class="tpl-dd-txt"><span class="tpl-dd-n">${_et(t.name)}</span>${(t.desc||t.description)?`<span class="tpl-dd-d">${_et(t.desc||t.description)}</span>`:''}</span>
      <span class="tpl-dd-c">${(t.channels||[]).length} CH</span>
      ${mine?`<button type="button" class="tpl-dd-del" title="Supprimer ce template" aria-label="Supprimer" onclick="event.stopPropagation();delUserTpl('${_jsq(t.id)}')"><i class="ti ti-trash"></i></button>`:''}
    </div>`;
  el.innerHTML=(USER_TPLS.length?'<div class="tpl-dd-grp">Mes templates</div>'+USER_TPLS.map(t=>row(t,true)).join(''):'')
    +(BLTPLS.length?'<div class="tpl-dd-grp">Modèles PatchFlow</div>'+BLTPLS.map(t=>row(t,false)).join(''):'')
    ||'<div class="tpl-dd-none">Aucun template.</div>';
}

async function applyTemplate(tplId){
  // Find template
  const tpl=[...BLTPLS,...USER_TPLS].find(t=>t.id===tplId);
  if(!tpl){toast('Template introuvable.');return;}
  if(!CUR_SHOW){toast('Aucun show actif.');return;}

  let chs=tpl.channels||[];
  if(chs.length===0){toast('Ce template est vide.');return;}

  const msg=TPL_MODE==='replace'
    ?`Remplacer les ${CHS.length} canaux actuels par "${tpl.name}" (${chs.length} canaux) ?`
    :`Ajouter les ${chs.length} canaux de "${tpl.name}" à la suite ?`;
  if(!confirm(msg))return;

  if(TPL_MODE==='replace'){
    const ids=CHS.map(r=>r.id);
    if(ids.length){const {error:de}=await sb.from('channels').delete().in('id',ids);if(de){toast('Erreur suppression : '+de.message);return;}}
    CHS=[];
  }

  /* ── Enforce plan channel limit ── */
  {
    const limit = planLimit('max_channels');
    if (limit !== Infinity) {
      const baseCount = CHS.length; /* CHS already empty after replace */
      const totalChs = chs.length;
      const projected = baseCount + totalChs;
      if (projected > limit) {
        const available = limit - baseCount;
        if (available <= 0) { showUpgradeModal('max_channels'); return; }
        chs = chs.slice(0, available);
        toast('⚠️ Plan Gratuit : limite de ' + limit + ' canaux — ' + available + ' sur ' + totalChs + ' canaux du template chargés. Passez Pro pour des canaux illimités.');
      }
    }
  }

  const offset=CHS.length;
  const toInsert=chs.map((r,i)=>{
    const row={
      show_id:CUR_SHOW.id,
      ch:offset+i+1,
      short_name:r.short_name||'',
      long_name:r.long_name||'',
      source:r.source||'',
      mic:r.mic||'',
      gain:r.gain||0,
      phantom:!!r.phantom,
      iem_group:r.iem_group||'',
      foh:!!r.foh,
      mon:!!r.mon,
      bc:!!r.bc,
      note:r.note||'',
    };
    if(_patchColReady) row.patch_id=CUR_PATCH_ID;
    return row;
  });

  const {data,error}=await sb.from('channels').insert(toInsert).select();
  if(error){toast('Erreur Supabase : '+error.message);console.error(error);return;}

  CHS=[...CHS,...(data||[])].sort((a,b)=>a.ch-b.ch);
  renderTable();
  toast(`✓ "${tpl.name}" appliqué — ${chs.length} canaux chargés`);
}


function toggleSP(){const p=document.getElementById('side-panel');p.classList.contains('show')?closeSP():openSP();}
function openSP(){
  var p=document.getElementById('side-panel');
  try{ closeNotifs(); }catch(e){}
  /* Ordinateur : la fenêtre s'ouvre à côté du menu, à la hauteur du nom du show */
  var hd=document.querySelector('.nav-show-hd'), top='';
  if(window.innerWidth>=641 && hd && hd.offsetParent){ top=Math.max(12,Math.min(hd.getBoundingClientRect().top-6, window.innerHeight-420))+'px'; }
  p.style.top=top;
  p.classList.add('show');
  document.getElementById('sp-ov').classList.add('show');
  var q=document.getElementById('sw-q'); if(q){ q.value=''; if(window.innerWidth>=641) setTimeout(function(){ try{ q.focus(); }catch(e){} },30); }
  renderSPShows();
}
function closeSP(){document.getElementById('side-panel').classList.remove('show');document.getElementById('sp-ov').classList.remove('show');closePrev();}
/* Dates de show : enregistrées en ISO AAAA-MM-JJ (accepté par une colonne
   text comme date). Les anciennes saisies libres « 15/05/2025 » sont relues. */
function _showDateISO(v){
  if(!v) return '';
  var s=String(v).trim(), m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(!m){
    var f=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2}|\d{4})$/);
    if(!f) return '';
    m=[null, f[3].length===2?'20'+f[3]:f[3], ('0'+f[2]).slice(-2), ('0'+f[1]).slice(-2)];
  }
  var y=+m[1], mo=+m[2], d=+m[3];
  var dt=new Date(y, mo-1, d);
  if(dt.getFullYear()!==y || dt.getMonth()!==mo-1 || dt.getDate()!==d) return '';
  return m[1]+'-'+m[2]+'-'+m[3];
}
function _fmtShowDate(v){
  var iso=_showDateISO(v);
  if(!iso) return v?String(v):'';
  var p=iso.split('-');
  /* Date locale (pas new Date('AAAA-MM-JJ') : interprété en UTC, décalé d'un jour à l'ouest). */
  return new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'});
}
/* Liste du sélecteur de session : à venir (de la plus proche à la plus lointaine), puis passées */
function renderSPShows(){
  const el=document.getElementById('sp-shows');if(!el)return;
  const _e2=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  var q=(document.getElementById('sw-q')?.value||'').trim().toLowerCase();
  var today=_todayISO();
  var list=SHOWS.filter(function(s){ return !q || String(s.name||'').toLowerCase().indexOf(q)>=0 || String(s.venue||'').toLowerCase().indexOf(q)>=0; });
  if(!list.length){
    el.innerHTML='<div class="nf-empty"><i class="ti '+(q?'ti-search-off':'ti-calendar-plus')+'"></i><span>'+(q?'Aucune session ne correspond.':'Aucune session pour l\'instant.')+'</span></div>';
    return;
  }
  var iso=function(s){ return _showDateISO(s.show_date); };
  var up=list.filter(function(s){ var i=iso(s); return !i||i>=today; }).sort(function(a,b){ var x=iso(a),y=iso(b); if(!x&&!y) return 0; if(!x) return 1; if(!y) return -1; return x.localeCompare(y); });
  var past=list.filter(function(s){ var i=iso(s); return i&&i<today; }).sort(function(a,b){ return iso(b).localeCompare(iso(a)); });
  var row=function(s){
    var i=iso(s), d=i?_isoToDate(i):null, cur=s.id===CUR_SHOW?.id;
    var sub=[s.venue?_e2(s.venue):'', i?_countdownTxt(i):'Sans date'].filter(Boolean).join(' · ');
    return '<button type="button" class="sw-row'+(cur?' on':'')+'" onclick="spSwitch(\''+_jsq(s.id)+'\')"'+(cur?' aria-current="true"':'')+'>'
      +'<span class="sw-date">'+(d?'<b>'+d.getDate()+'</b><i>'+_e2(d.toLocaleDateString('fr-FR',{month:'short'}).replace('.','').toUpperCase())+'</i>':'<span class="ti ti-calendar-off"></span>')+'</span>'
      +'<span class="sw-info"><span class="sw-name">'+_e2(s.name)+'</span><span class="sw-sub">'+sub+'</span></span>'
      +(cur?'<span class="ti ti-check sw-ck"></span>':'')
    +'</button>';
  };
  el.innerHTML=(up.length?'<div class="sw-grp">À venir</div>'+up.map(row).join(''):'')
    +(past.length?'<div class="sw-grp">Passées</div>'+past.map(row).join(''):'');
}
async function spSwitch(id){await switchShow(id);closeSP();}

